pub fn count_uppercase(text: &Vec<char>) -> u64 {
    // Count chars whose Unicode scalar value matches ASCII 'A'..='Z' (65..=90).
    // This excludes lowercase, digits, symbols, whitespace, and any non-ASCII letters.
    text.iter()
        .filter(|&&c| matches!(c, 'A'..='Z'))
        .count() as u64
}